--- /dev/null
+++ b/src/main/java/team/startup/gwangjutalentfestival/domain/monitoring/client/MlServerClient.java
@@ -0,0 +1,76 @@
+package team.startup.gwangjutalentfestival.domain.monitoring.client;
+
+import lombok.extern.slf4j.Slf4j;
+import org.springframework.beans.factory.annotation.Qualifier;
+import org.springframework.http.MediaType;
+import org.springframework.stereotype.Component;
+import org.springframework.web.client.RestClient;
+import team.startup.gwangjutalentfestival.domain.monitoring.client.dto.MlAnomalyScoreRequest;
+import team.startup.gwangjutalentfestival.domain.monitoring.client.dto.MlAnomalyScoreResponse;
+import team.startup.gwangjutalentfestival.domain.monitoring.properties.MlProperties;
+
+import java.util.Optional;
+import java.util.Set;
+
+@Slf4j
+@Component
+public class MlServerClient {
+
+    private static final Set<String> VALID_LABELS = Set.of("anomaly", "normal");
+
+    private final RestClient mlRestClient;
+    private final MlProperties mlProperties;
+
+    public MlServerClient(
+            @Qualifier("mlRestClient") RestClient mlRestClient,
+            MlProperties mlProperties
+    ) {
+        this.mlRestClient = mlRestClient;
+        this.mlProperties = mlProperties;
+    }
+
+    public Optional<MlAnomalyScoreResponse> call(MlAnomalyScoreRequest request) {
+        if (!mlProperties.enabled() || mlProperties.baseUrl().isBlank()) {
+            return Optional.empty();
+        }
+
+        try {
+            MlAnomalyScoreResponse response = mlRestClient.post()
+                    .uri(normalizeBaseUrl(mlProperties.baseUrl()) + "/anomaly-score")
+                    .contentType(MediaType.APPLICATION_JSON)
+                    .body(request)
+                    .retrieve()

[LANG-1836] Make TypeUtils.containsTypeVariables and unrollVariables honour the owner type of a ParameterizedType (#1812)


---
 .../apache/commons/lang3/reflect/TypeUtils.java    | 159 ++++++++++---
 .../commons/lang3/reflect/TypeUtilsTest.java       | 261 +++++++++++++++++++++
 2 files changed, 384 insertions(+), 36 deletions(-)

diff --git a/src/main/java/org/apache/commons/lang3/reflect/TypeUtils.java b/src/main/java/org/apache/commons/lang3/reflect/TypeUtils.java
index 74feb8848..ecd4dfe64 100644
--- a/src/main/java/org/apache/commons/lang3/reflect/TypeUtils.java
+++ b/src/main/java/org/apache/commons/lang3/reflect/TypeUtils.java
@@ -371,42 +371,66 @@ private static <T> String classToString(final Class<T> cls) {

     /**
      * Tests, recursively, whether any of the type parameters associated with {@code type} are bound to variables.
+     * <p>
+     * The owner type of a parameterized type, for example {@code Outer<T>} of {@code Outer<T>.Inner}, is checked as well.
+     * </p>
      *
      * @param type The type to check for type variables.
      * @return Whether any of the type parameters associated with {@code type} are bound to variables.
      * @since 3.2
      */
     public static boolean containsTypeVariables(final Type type) {
+        return containsTypeVariables(type, newIdentitySet());
+    }
+
+    /**
+     * Creates a set that compares by identity, so that cycle detection never calls {@code hashCode()} or {@code equals()} of a custom {@link Type}.
+     *
